commands:
$gpus = Get-CimInstance Win32_VideoController | Where-Object { $_.PNPDeviceID -like 'PCI\VEN_*' }
Write-Host "GPUs found: $($gpus.Count)"

foreach ($g in $gpus) {
    Write-Host "`n$($g.Name)"
    $enumKey = "HKLM:\SYSTEM\ControlSet001\Enum\$($g.PNPDeviceID)"

    try {
        $driver = (Get-ItemProperty -Path $enumKey -Name 'Driver' -ErrorAction Stop).Driver
        $classKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\$driver"
        Write-Host "Path: $classKey"

        New-ItemProperty -Path $classKey -Name 'RMHdcpKeyglobZero' -PropertyType DWord -Value 1 -Force
        Write-Host "RMHdcpKeyglobZero = 1"

    } catch {
        Write-Host "Error: $($_.Exception.Message)"
    }
}

